import copy
import unittest
from patcher import merge_patch
class PatchTests(unittest.TestCase):
    def test_add_and_replace(self):
        self.assertEqual(merge_patch({'a':1,'b':2},{'a':3,'c':4}),{'a':3,'b':2,'c':4})
    def test_null_removes(self):
        self.assertEqual(merge_patch({'a':1,'b':2},{'a':None,'missing':None}),{'b':2})
    def test_recursive(self):
        self.assertEqual(merge_patch({'a':{'x':1,'y':2}},{'a':{'x':None,'z':3}}),{'a':{'y':2,'z':3}})
    def test_array_replacement(self):
        self.assertEqual(merge_patch({'a':[1,2,3]},{'a':[9]}),{'a':[9]})
    def test_scalar_document(self):
        for doc in [None,3,True,'old',[1]]:
            with self.subTest(doc=doc):self.assertEqual(merge_patch(doc,{'a':{'b':2}}),{'a':{'b':2}})
    def test_non_object_patch(self):
        for patch in [None,False,5,2.5,'new',[{'x':1}]]:
            with self.subTest(patch=patch):self.assertEqual(merge_patch({'a':1},patch),patch)
    def test_nested_object_over_scalar(self):
        self.assertEqual(merge_patch({'a':7},{'a':{'b':None,'c':{}}}),{'a':{'c':{}}})
    def test_no_mutation(self):
        doc={'a':{'x':[1]},'keep':[2]};patch={'a':{'y':[3]}}
        before=copy.deepcopy((doc,patch));result=merge_patch(doc,patch)
        self.assertEqual((doc,patch),before)
        result['a']['x'].append(8);result['a']['y'].append(8);result['keep'].append(8)
        self.assertEqual((doc,patch),before)
    def test_scalar_patch_copy(self):
        patch=[{'a':[1]}];result=merge_patch({},patch);result[0]['a'].append(2)
        self.assertEqual(patch,[{'a':[1]}])
    def test_invalid_values(self):
        invalid=[(1,),{1:2},{'x':{1}},float('nan'),float('inf'),{'a':[float('-inf')]}]
        for value in invalid:
            for doc,patch in [(value,{}),({},value)]:
                with self.subTest(doc=repr(doc),patch=repr(patch)):
                    with self.assertRaises(ValueError):merge_patch(doc,patch)
if __name__=='__main__':unittest.main()

