import random
import unittest
from limiter import RateLimiter
class LimiterTests(unittest.TestCase):
    def make(self,limit=2,window=10):
        clock=[10.0];return RateLimiter(limit,window,lambda:clock[0]),clock
    def test_limit(self):
        limiter,t=self.make();self.assertIs(limiter.allow('a'),True);self.assertIs(limiter.allow('a'),True);self.assertIs(limiter.allow('a'),False)
    def test_exact_expiry(self):
        limiter,t=self.make(1);self.assertTrue(limiter.allow('a'));t[0]=19.999;self.assertFalse(limiter.allow('a'));t[0]=20;self.assertTrue(limiter.allow('a'))
    def test_denied_does_not_extend(self):
        limiter,t=self.make(1);self.assertTrue(limiter.allow('a'));t[0]=19;self.assertFalse(limiter.allow('a'));t[0]=20;self.assertTrue(limiter.allow('a'))
    def test_key_isolation(self):
        limiter,t=self.make(1);self.assertTrue(limiter.allow('a'));self.assertTrue(limiter.allow('b'));self.assertFalse(limiter.allow('a'));self.assertFalse(limiter.allow('b'))
    def test_partial_expiry(self):
        limiter,t=self.make();self.assertTrue(limiter.allow('a'));t[0]=15;self.assertTrue(limiter.allow('a'));t[0]=20;self.assertTrue(limiter.allow('a'));self.assertFalse(limiter.allow('a'));t[0]=25;self.assertTrue(limiter.allow('a'))
    def test_invalid_constructor(self):
        for limit in [0,-1,True,1.5,'2',None]:
            with self.subTest(limit=limit):
                with self.assertRaises(ValueError):RateLimiter(limit,10)
        for window in [0,-1,True,float('inf'),float('nan'),'10',None]:
            with self.subTest(window=window):
                with self.assertRaises(ValueError):RateLimiter(2,window)
        with self.assertRaises(ValueError):RateLimiter(2,10,3)
    def test_invalid_key_without_clock_call(self):
        calls=[];limiter=RateLimiter(1,10,lambda:calls.append(1) or 10)
        for key in ['',None,1,False]:
            with self.subTest(key=key):
                with self.assertRaises(ValueError):limiter.allow(key)
        self.assertEqual(calls,[]);self.assertTrue(limiter.allow('a'));self.assertEqual(len(calls),1)
    def test_invalid_clock(self):
        limiter,t=self.make(1);self.assertTrue(limiter.allow('a'))
        for value in [True,None,'10',float('inf'),float('nan')]:
            t[0]=value
            with self.subTest(value=repr(value)):
                with self.assertRaises(ValueError):limiter.allow('b')
        t[0]=10;self.assertTrue(limiter.allow('b'));self.assertFalse(limiter.allow('a'))
    def test_clock_backwards_is_global_and_atomic(self):
        limiter,t=self.make(1);self.assertTrue(limiter.allow('a'))
        for value in [9,9.5]:
            t[0]=value
            with self.subTest(value=value):
                with self.assertRaises(ValueError):limiter.allow('b')
        t[0]=10;self.assertTrue(limiter.allow('b'))
    def test_default_clock(self):
        limiter=RateLimiter(1,10);self.assertTrue(limiter.allow('a'));self.assertFalse(limiter.allow('a'))
    def test_reference_sequence(self):
        limiter,t=self.make(3,5);history={};rng=random.Random(1234)
        for i in range(100):
            t[0]+=rng.choice([0,0.5,1,5]);key=rng.choice(['a','b','c'])
            history[key]=[x for x in history.get(key,[]) if x>t[0]-5]
            expected=len(history[key])<3
            if expected:history[key].append(t[0])
            with self.subTest(i=i):self.assertIs(limiter.allow(key),expected)
if __name__=='__main__':unittest.main()

