import unittest
from paths import normalize_path
class PathTests(unittest.TestCase):
    def test_root(self):
        for value in ['/','///','/./','//.//']:
            with self.subTest(value=value):self.assertEqual(normalize_path(value),'/')
    def test_repeated_separators(self):
        self.assertEqual(normalize_path('//a///b//'),'/a/b')
    def test_dot(self):
        self.assertEqual(normalize_path('/a/./b/.'),'/a/b')
    def test_parent(self):
        self.assertEqual(normalize_path('/a/b/../c'),'/a/c');self.assertEqual(normalize_path('/a/..'),'/')
    def test_above_root(self):
        for value in ['/..','/../a','/a/../../b','//./../']:
            with self.subTest(value=value):
                with self.assertRaises(ValueError):normalize_path(value)
    def test_invalid_input(self):
        for value in [None,False,1,[],{},'', 'a/b',' ./a','/a'+chr(0)+'b']:
            with self.subTest(value=repr(value)):
                with self.assertRaises(ValueError):normalize_path(value)
    def test_unicode_spaces_and_literal_dots(self):
        self.assertEqual(normalize_path('/资料/ a /.../..hidden/'),'/资料/ a /.../..hidden')
    def test_no_expansion(self):
        self.assertEqual(normalize_path('/~/$HOME/%TMP%'),'/~/$HOME/%TMP%')
    def test_backslash_is_literal(self):
        value='/a'+chr(92)+'b/c';self.assertEqual(normalize_path(value),value)
    def test_idempotence(self):
        for value in ['/','/a//b/../c/','/./a/.../','/资料//x/../y']:
            with self.subTest(value=value):
                normalized=normalize_path(value);self.assertEqual(normalize_path(normalized),normalized)
if __name__=='__main__':unittest.main()

