import copy
import unittest
from joiner import left_join
class JoinTests(unittest.TestCase):
    def test_basic_and_prefix(self):
        self.assertEqual(left_join([{'id':'a','n':1}],[{'id':'a','n':2}],'id'),[{'id':'a','n':1,'right.n':2}])
    def test_left_order_and_duplicates(self):
        left=[{'id':'b','x':1},{'id':'a','x':2},{'id':'b','x':3}]
        self.assertEqual([r['right.y'] for r in left_join(left,[{'id':'a','y':10},{'id':'b','y':20}],'id')],[20,10,20])
    def test_unmatched_and_union_columns(self):
        result=left_join([{'id':'a'},{'id':'missing'}],[{'id':'a','x':1},{'id':'b','y':2}],'id')
        self.assertEqual(result,[{'id':'a','right.x':1,'right.y':None},{'id':'missing','right.x':None,'right.y':None}])
    def test_empty_sides(self):
        self.assertEqual(left_join([],[],'id'),[]);self.assertEqual(left_join([{'id':'a'}],[],'id'),[{'id':'a'}])
    def test_custom_key(self):
        self.assertEqual(left_join([{'code':'x'}],[{'code':'x','id':'kept'}],'code'),[{'code':'x','right.id':'kept'}])
    def test_duplicate_right_is_error(self):
        with self.assertRaises(ValueError):left_join([],[{'id':'a'},{'id':'a'}],'id')
    def test_prefix_collision(self):
        with self.assertRaises(ValueError):left_join([{'id':'missing','right.x':0}],[{'id':'a','x':1}],'id')
    def test_invalid_parameters(self):
        for left,right,key in [(None,[],'id'),([],{},'id'),([],[],''),([],[],1)]:
            with self.subTest(left=left,right=right,key=key):
                with self.assertRaises(ValueError):left_join(left,right,key)
    def test_invalid_rows(self):
        for row in [None,[],{}, {'id':''},{'id':1},{'id':True},{'id':'a',1:2},{'id':'a','':2}]:
            for left,right in [([row],[]),([],[row])]:
                with self.subTest(row=repr(row),side='left' if left else 'right'):
                    with self.assertRaises(ValueError):left_join(left,right,'id')
    def test_deep_copy_inputs(self):
        left=[{'id':'a','x':[1]}];right=[{'id':'a','y':{'z':[2]}}];before=copy.deepcopy((left,right))
        result=left_join(left,right,'id');result[0]['x'].append(3);result[0]['right.y']['z'].append(4)
        self.assertEqual((left,right),before)
    def test_duplicate_output_rows_are_independent(self):
        result=left_join([{'id':'a'},{'id':'a'}],[{'id':'a','x':[1]}],'id')
        result[0]['right.x'].append(2);self.assertEqual(result[1]['right.x'],[1])
if __name__=='__main__':unittest.main()
